SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{}',true);
SELECT clock_timestamp() AS captured_at,
 public.consume_recovery_session_v1(NULL::uuid,NULL::uuid) IS FALSE AS unbound_recovery_denied,
 NOT has_function_privilege('anon','public.consume_recovery_session_v1(uuid,uuid)','EXECUTE') AS anonymous_execute_denied;
ROLLBACK;
